import {selectCalendarDate} from './calendar-picker-actions.mjs';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';import{readFile,writeFile}from'node:fs/promises';import{load}from'cheerio';import{chromium}from'playwright';import{serveStatic}from'../../engine/static.mjs';import{collectCalendarPresentation,calendarPresentation}from'../../scripts/calendar-presentation.mjs';import{applyComponents}from'../../scripts/component-export.mjs';import{parseContent}from'../../scripts/source-project.mjs';import path from'node:path';
const generated=process.argv.includes('--generated');
const artifact=path.resolve('artifacts/platform/events-heldout'),project=path.join(artifact,'project'),routes=JSON.parse(await readFile(path.join(project,'routes.json'))),events=[];
for(const r of routes.filter(r=>r.route.startsWith('/event/'))){const p=parseContent(await readFile(path.join(project,'content',r.collection,r.slug+'.md'),'utf8'),'event');events.push({route:r.route,title:p.meta.title,start:p.meta.event.start,end:p.meta.event.end,allDay:p.meta.event.all_day,description:p.meta.description,venue:p.meta.event.venue.venue});}
const manifest={schema:'website-cloner-calendar/v1',events},registry=new Map();for(const r of routes.filter(r=>r.route.startsWith('/events/'))){const $=load(await readFile(path.join(project,'output',r.route,'index.html'),'utf8'));collectCalendarPresentation($,{manifestRoute:'/assets/test-calendar.json',manifest},registry);}const presentation=calendarPresentation([...registry.values()][0]);assert.deepEqual(presentation.missing,[]);
let server,browser;const cases=[];try{server=await serveStatic(path.join(project,'output'));browser=await chromium.launch({channel:'chrome'});for(const width of [1440,390]){const page=await browser.newPage({viewport:{width,height:900}}),route='/events/month/2028-03/';if(!generated)await page.route(server.url+'/**',async r=>{const url=new URL(r.request().url());if(url.pathname==='/assets/test-calendar.json')return r.fulfill({json:manifest});if(url.pathname==='/assets/test-calendar.presentation.json')return r.fulfill({json:presentation});if(url.pathname===route){const $=load(await readFile(path.join(project,'output',route,'index.html'),'utf8'));$('.tribe-events-view').attr('data-migration-calendar','/assets/test-calendar.json');applyComponents($);return r.fulfill({contentType:'text/html',body:$.html()});}return r.continue();});await page.goto(server.url+route,{waitUntil:'networkidle'});
const next=page.locator('.tribe-events-c-top-bar__nav-link--next:visible,.tribe-events-c-nav__next:visible').first();await next.click();await page.waitForURL('**calendar-date=2028-04-01').catch(async error=>{console.log(JSON.stringify({url:page.url(),status:await page.locator('[role=status]').allTextContents(),datepicker:await page.locator('.tribe-events-c-top-bar__datepicker-time').getAttribute('datetime')}));throw error;});assert.equal(await page.locator('.tribe-events-calendar-month__week').count(),5);assert.ok(await page.locator('time[datetime="2028-04-30"]').count());
await selectCalendarDate(page,'2028-03-01');await page.waitForURL('**calendar-date=2028-03-01');assert.ok(await page.locator('.tribe-events-calendar-month__multiday-event--width-2.tribe-events-calendar-month__multiday-event--start').count());
if(width===390){await page.locator('[data-calendar-day="2028-03-11"]').click();const panel=page.locator('.tribe-events-calendar-month-mobile-events__mobile-day--show');assert.ok(await panel.isVisible());assert.match(await panel.textContent(),/Coastal Design Lab/);await page.keyboard.press('Escape');assert.equal(await page.locator('[data-calendar-day="2028-03-11"]').getAttribute('aria-expanded'),'false');assert.equal(await page.locator('.tribe-events-calendar-month-mobile-events__mobile-day--show').count(),0);}
const ids=await page.locator('[id]').evaluateAll(es=>es.map(e=>e.id));assert.equal(new Set(ids).size,ids.length);cases.push({runtimeSHA256:createHash('sha256').update(await page.locator('script[data-cloner-component=calendar]').textContent()).digest('hex'),width,monthNavigation:true,multidaySplit:true,mobileSelection:width===390,uniqueIDs:true});await page.close();}await writeFile(path.join(artifact,generated?'month-calendar-generated-check.json':'month-calendar-candidate-check.json'),JSON.stringify({scope:generated?'Generated month controls':'Candidate month controls using installed export fragments; visual parity pending',cases},null,2));console.log(JSON.stringify({cases:cases.length}));}finally{await browser?.close();await server?.close();}
